{"Time":"2024-01-01T00:00:00.002Z","Action":"pass","Package":"example.com/foo","Test":"TestA","Elapsed":0.001}
{"Time":"2024-01-01T00:00:00.003Z","Action":"pass","Package":"example.com/foo","Elapsed":0.002}
