                sb.WriteString("  ")
            }
            sb.WriteString(strings.TrimSpace(cell)) // not
            // Actually we need to preserve padding: We'll write cell as is but without outer border
            // For plain, they seem to have header with padded spaces inside column width, but without vertical bars, just spaces.
