        // To avoid incomplete, we will just render basic table for plain
        // But we already have widths computed, we can output header and rows with plain style: each row is "  " + padded cells joined by "   "?
        // Let's approximate: We'll output header line with cells padded to widths and prefixed with two spaces
        sb.Reset()
