    // We'll reuse basic failure logic for plain: same box
    for _, p := range pkgs {
        if p.Status != "FAIL" && p.Status != "PANIC" {
            continue
        }
        display := displayNames[p.Name]
        var headerStatus string
        if p.Status == "PANIC" {
            headerStatus = "PANIC"
        } else {
            headerStatus = "FAIL"
        }
        inner := "   " + headerStatus + "  package: " + display
        if p.Panic && p.PanicTest != "" {
            inner += " • " + p.PanicTest
        }
        inner += "   "
        innerLen := utf8.RuneCountInString(inner)
        var box strings.Builder
        if useColor {
            box.WriteString("\x1b[38;5;103m┏")
            box.WriteString(strings.Repeat("━", innerLen))
            box.WriteString("┓\x1b[0m\n")
            box.WriteString("\x1b[38;5;103m┃\x1b[0m")
            box.WriteString("   \x1b[91m\x1b[91m" + headerStatus + "\x1b[0m\x1b[0m  package: " + display)
            if p.Panic && p.PanicTest != "" {
                box.WriteString(" • " + p.PanicTest)
            }
            box.WriteString("   ")
            box.WriteString("\x1b[38;5;103m┃\x1b[0m\n")
            box.WriteString("\x1b[38;5;103m┗")
            box.WriteString(strings.Repeat("━", innerLen))
            box.WriteString("┛\x1b[0m\n")
        } else {
            box.WriteString("┏")
            box.WriteString(strings.Repeat("━", innerLen))
            box.WriteString("┓\n")
            box.WriteString("┃")
            box.WriteString(inner)
            box.WriteString("┃\n")
            box.WriteString("┗")
            box.WriteString(strings.Repeat("━", innerLen))
            box.WriteString("┛\n")
        }
        box.WriteString("\n\n\n")
        if p.Status == "PANIC" {
            for _, out := range p.PanicOutputs {
                box.WriteString(out)
            }
            box.WriteString("\n")
        } else {
            var failTests []*TestInfo
            for _, key := range getTestOrderForPackage(tests, p.Name) {
                ti := tests[key]
                if ti.Status == "FAIL" {
                    failTests = append(failTests, ti)
                }
            }
            if len(failTests) == 0 {
                for _, out := range p.PackageOutputs {
                    if strings.Contains(out, "coverage:") {
                        continue
                    }
                    box.WriteString(out)
                }
            } else {
                for idx, ti := range failTests {
                    outs := p.TestOutputs[ti.Name]
                    for _, o := range outs {
                        box.WriteString(o)
                    }
                    if idx < len(failTests)-1 {
                        box.WriteString("\n")
                        box.WriteString(strings.Repeat("─", 96))
                        box.WriteString("\n")
                        box.WriteString(strings.Repeat(" ", 96))
                        box.WriteString("\n\n")
                    }
                }
            }
            box.WriteString("\n")
        }
        os.Stdout.WriteString(box.String())
    }

    if len(pkgs) == 0 {
        return
    }
    headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
    var pkgRows [][]string
    for _, p := range pkgs {
        var elapsedStr string
        if p.Cached {
            elapsedStr = "(cached)"
        } else {
            if p.Status == "PANIC" {
                elapsedStr = "0.00s"
            } else {
                elapsedStr = fmt.Sprintf("%.2fs", p.Elapsed)
            }
        }
        coverStr := p.Cover
        var passStr, failStr, skipStr string
        if p.Status == "PANIC" || p.Status == "NOTEST" {
            passStr = "--"
            failStr = "--"
            skipStr = "--"
        } else if p.Status == "" {
            passStr = strconv.Itoa(p.Pass)
            failStr = strconv.Itoa(p.Fail)
            skipStr = strconv.Itoa(p.Skip)
        } else {
            passStr = strconv.Itoa(p.Pass)
            failStr = strconv.Itoa(p.Fail)
            skipStr = strconv.Itoa(p.Skip)
        }
        display := displayNames[p.Name]
        status := p.Status
        row := []string{status, elapsedStr, display, coverStr, passStr, failStr, skipStr}
        pkgRows = append(pkgRows, row)
        if p.Status == "NOTEST" {
            second := []string{"", "", p.NotestMsg, "", "", "", ""}
            pkgRows = append(pkgRows, second)
        }
    }
    colCount := 7
    widths := make([]int, colCount)
    for i, h := range headers {
        widths[i] = utf8.RuneCountInString(h) + 2
    }
    for _, r := range pkgRows {
        for i, c := range r {
            l := utf8.RuneCountInString(c) + 2
            if l > widths[i] {
                widths[i] = l
            }
        }
    }
    // Render plain package table
    var sb strings.Builder
    // Header
    for i, h := range headers {
        w := widths[i]
        visLen := utf8.RuneCountInString(h)
        pad := w - visLen
        left := pad / 2
        right := pad - left
        cell := strings.Repeat(" ", left) + h + strings.Repeat(" ", right)
        if i > 0 {
            sb.WriteString("   ")
        } else {
            sb.WriteString("  ")
        }
        sb.WriteString(cell)
    }
    sb.WriteString("\n")
    totalWidth := 0
    for _, w := range widths {
        totalWidth += w + 3
    }
    sb.WriteString(strings.Repeat(" ", totalWidth) + "\n")
    for _, r := range pkgRows {
        for i, c := range r {
            w := widths[i]
            var cell string
            if i == 0 && c != "" && useColor {
                colored := colorStatus(c, true)
                visLen := utf8.RuneCountInString(c)
                pad := w - visLen
                left := pad / 2
                right := pad - left
                cell = strings.Repeat(" ", left) + colored + strings.Repeat(" ", right)
            } else {
                visLen := utf8.RuneCountInString(c)
                pad := w - visLen
                if i == 2 {
                    if c == "" {
                        cell = strings.Repeat(" ", w)
                    } else {
                        cell = " " + c + strings.Repeat(" ", pad-1)
                    }
                } else {
                    left := pad / 2
                    right := pad - left
                    cell = strings.Repeat(" ", left) + c + strings.Repeat(" ", right)
                }
            }
            if i > 0 {
                sb.WriteString("   ")
            } else {
                sb.WriteString("  ")
            }
            sb.WriteString(cell)
        }
        sb.WriteString("\n")
    }
    os.Stdout.WriteString(sb.String())
}

func renderMarkdown(pkgs []*PackageInfo, testRows []*TestInfo, displayNames map[string]string, tests map[string]*TestInfo, useColor bool) {
    // For markdown, per-package details
    byPkg := map[string][]*TestInfo{}
    for _, ti := range testRows {
        byPkg[ti.Package] = append(byPkg[ti.Package], ti)
    }
    for _, p := range pkgs {
        tlist := byPkg[p.Name]
        if len(tlist) == 0 {
            continue
        }
        display := displayNames[p.Name]
        pass, fail, skip := 0, 0, 0
        for _, ti := range tlist {
            switch ti.Status {
            case "PASS":
                pass++
            case "FAIL":
                fail++
            case "SKIP":
                skip++
            }
        }
        fmt.Fprintf(os.Stdout, "## 📦 Package **`%s`**\n\n", display)
        fmt.Fprintf(os.Stdout, "Tests: ✓ %d passed | %d skipped | %d failed\n\n", pass, skip, fail)
        fmt.Fprint(os.Stdout, "<details>\n\n<summary>Click for test summary</summary>\n\n")
        fmt.Fprint(os.Stdout, "| Status | Elapsed | Test |\n")
        fmt.Fprint(os.Stdout, "|--------|---------|------|\n")
        for _, ti := range tlist {
            status := ti.Status
            if useColor {
                // markdown with colors uses emoji? We'll just use plain status with maybe color?
                // For now, plain
            }
            elapsed := fmt.Sprintf("%.2f", ti.Elapsed)
            testName := ti.Name
            if smallscreenFlag && strings.Contains(testName, "/") && len(testName) > 30 {
                parts := strings.Split(testName, "/")
                fmt.Fprintf(os.Stdout, "|  %s  |  %s   | %s |\n", status, elapsed, parts[0])
                for i := 1; i < len(parts); i++ {
                    seg := "  /" + parts[i]
                    if visibleLen(seg) > 34 {
                        runes := []rune(seg)
                        first := string(runes[:32]) + " …"
                        fmt.Fprintf(os.Stdout, "|        |         | %s |\n", first)
                        remainder := "   " + string(runes[32:])
                        fmt.Fprintf(os.Stdout, "|        |         | %s |\n", remainder)
                    } else {
                        fmt.Fprintf(os.Stdout, "|        |         | %s |\n", seg)
                    }
                }
            } else {
                fmt.Fprintf(os.Stdout, "|  %s  |  %s   | %s |\n", status, elapsed, testName)
            }
        }
        fmt.Fprint(os.Stdout, "</details>\n\n\n")
    }

    for _, p := range pkgs {
        if p.Status != "FAIL" && p.Status != "PANIC" {
            continue
        }
        display := displayNames[p.Name]
        if p.Status == "PANIC" {
            testPart := ""
            if p.PanicTest != "" {
                testPart = " • " + p.PanicTest
            }
            fmt.Fprintf(os.Stdout, "## %s • %s%s\n", p.Status, display, testPart)
            for _, out := range p.PanicOutputs {
                fmt.Fprint(os.Stdout, out)
            }
            fmt.Fprint(os.Stdout, "\n")
        } else {
            fmt.Fprintf(os.Stdout, "## FAIL • %s\n\n", display)
            fmt.Fprint(os.Stdout, "```\n")
            var failTests []*TestInfo
            for _, key := range getTestOrderForPackage(tests, p.Name) {
                ti := tests[key]
                if ti.Status == "FAIL" {
                    failTests = append(failTests, ti)
                }
            }
            if len(failTests) == 0 {
                for _, out := range p.PackageOutputs {
                    if strings.Contains(out, "coverage:") {
                        continue
                    }
                    fmt.Fprint(os.Stdout, out)
                }
            } else {
                for _, ti := range failTests {
                    outs := p.TestOutputs[ti.Name]
                    for _, o := range outs {
                        fmt.Fprint(os.Stdout, o)
                    }
                }
            }
            fmt.Fprint(os.Stdout, "```\n\n")
        }
    }

    if len(pkgs) == 0 {
        return
    }
    // Summary table markdown
    // Need to compute widths? For markdown, column widths affect padding but we can just output with minimal padding as earlier
    // We'll output header and separator and rows with padding similar to observed
    // For simplicity, output without extra padding, just "|  PASS  |  0.01s  | p       |  --   |  1   |  0   |  0   |" style but we need to compute widths to pad?
    // Earlier markdown rows had padding: "|  PASS  |  0.01s  | p       |  --   |  1   |  0   |  0   |"
    // That's with Status "  PASS  " (2 each side), Elapsed "  0.01s  " etc.
    // We'll compute widths as before and use them to pad

    headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
    // Build rows
    var rows [][]string
    for _, p := range pkgs {
        var elapsedStr string
        if p.Cached {
            elapsedStr = "(cached)"
        } else {
            if p.Status == "PANIC" {
                elapsedStr = "0.00s"
            } else {
                elapsedStr = fmt.Sprintf("%.2fs", p.Elapsed)
            }
        }
        coverStr := p.Cover
        var passStr, failStr, skipStr string
        if p.Status == "PANIC" || p.Status == "NOTEST" {
            passStr = "--"
            failStr = "--"
            skipStr = "--"
        } else {
            passStr = strconv.Itoa(p.Pass)
            failStr = strconv.Itoa(p.Fail)
            skipStr = strconv.Itoa(p.Skip)
        }
        display := displayNames[p.Name]
        status := p.Status
        if status == "" {
            status = ""
        }
        // For markdown with useColor, status may be "🟢 PASS" etc. Check: earlier markdown without nocolor gave "🟢 PASS" for PASS?
        // Let's test quickly: In earlier markdown without nocolor, we didn't capture. We saw markdown with color gave "🟢 PASS" for header? Actually we saw markdown pass table with no nocolor gave "🟢 PASS" ? Let's check: We ran markdown without nocolor for simple pass and got row "| 🟢 PASS |  0.01s  | p       |  --   |  1   |  0   |  0   |" ??? Wait we ran markdown without nocolor for p and got `| 🟢 PASS |  0.01s  | p       |  --   |  1   |  0   |  0   |` ? Let's verify.

        row := []string{status, elapsedStr, display, coverStr, passStr, failStr, skipStr}
        rows = append(rows, row)
        if p.Status == "NOTEST" {
            // markdown notest second line? Probably not needed
        }
    }
    // Compute widths
    colCount := 7
    widths := make([]int, colCount)
    for i, h := range headers {
        widths[i] = utf8.RuneCountInString(h) + 2
    }
    for _, r := range rows {
        for i, c := range r {
            l := utf8.RuneCountInString(c) + 2
            if l > widths[i] {
                widths[i] = l
            }
        }
    }
    // Also need to consider colored status with emoji? For PASS with color, status string becomes "🟢 PASS" (with emoji + space + PASS) length? Emoji counts as 2? But we can ignore for now.
    // For markdown, if useColor, status for PASS should be "🟢 PASS", FAIL "🔴 FAIL", etc? Let's check observed markdown with colors.
    // In earlier we tested markdown without nocolor for simple pass (p) and got with nocolor false (default) the output was "| Status  | Elapsed | Package | Cover | Pass | Fail | Skip |\n|---------|---------|---------|-------|------|------|------|\n| 🟢 PASS |  0.01s  | p       |  --   |  1   |  0   |  0   |\n" Actually we captured markdown with no nocolor gave that emoji? Let's see: We ran `run(sample, ["-format","markdown"])` without nocolor and got row with "🟢 PASS"? Wait we ran earlier: `rc,o,e=run(sample, ["-format","markdown"])` without nocolor gave `| Status  | Elapsed | Package | Cover | Pass | Fail | Skip |\n|---------|---------|---------|-------|------|------|------|\n| 🟢 PASS |  0.01s  | p       |  --   |  1   |  0   |  0   |\n` Actually we captured for markdown without nocolor but we printed repr? Let's check: In earlier markdown test without nocolor, the output for single package pass was not captured. We captured markdown with -nocolor for same. The version without nocolor we captured for plain? Wait for markdown pass we did with -nocolor. For color case we did plain? Let's test again quickly.

    // For now, implement color handling for markdown: if useColor, prefix status with emoji
    if useColor {
        for idx, r := range rows {
            status := r[0]
            var emoji string
            switch status {
            case "PASS":
                emoji = "🟢"
            case "FAIL":
                emoji = "🔴"
            case "PANIC":
                emoji = "🔴"
            case "SKIP":
                emoji = "🟡"
            case "NOTEST":
                emoji = "🟡"
            default:
                emoji = ""
            }
            if emoji != "" {
                rows[idx][0] = emoji + " " + status
            }
        }
        // recompute widths after emoji
        for i := range widths {
            widths[i] = utf8.RuneCountInString(headers[i]) + 2
        }
        for _, r := range rows {
            for i, c := range r {
                l := utf8.RuneCountInString(c) + 2
                if l > widths[i] {
                    widths[i] = l
                }
            }
        }
    }

    // Output markdown table
    fmt.Fprint(os.Stdout, "|")
    for i, h := range headers {
        w := widths[i]
        visLen := utf8.RuneCountInString(h)
        pad := w - visLen
        left := pad / 2
        right := pad - left
        cell := strings.Repeat(" ", left) + h + strings.Repeat(" ", right)
        fmt.Fprintf(os.Stdout, "%s|", cell)
    }
    fmt.Fprint(os.Stdout, "\n|")
    for i, w := range widths {
        // separator: dashes with length w, but markdown separator uses dashes without spaces: "--------" ?
        // Earlier markdown separator for package table was "|--------|---------|---------|-------|------|------|------|"
        // That's dashes equal to width? For Status column width 8, separator "--------" length 8
        // For Elapsed width 9, separator "---------" length 9
        // So separator cell is strings.Repeat("-", w)
        fmt.Fprintf(os.Stdout, "%s|", strings.Repeat("-", w))
        _ = i
    }
    fmt.Fprint(os.Stdout, "\n")
    for _, r := range rows {
        fmt.Fprint(os.Stdout, "|")
        for i, c := range r {
            w := widths[i]
            visLen := utf8.RuneCountInString(c)
            pad := w - visLen
            // Determine align: Package left, others center
            var cell string
            if i == 2 { // Package left
                if c == "" {
                    cell = strings.Repeat(" ", w)
                } else {
                    cell = " " + c + strings.Repeat(" ", pad-1)
                }
            } else {
                left := pad / 2
                right := pad - left
                cell = strings.Repeat(" ", left) + c + strings.Repeat(" ", right)
            }
            fmt.Fprintf(os.Stdout, "%s|", cell)
        }
        fmt.Fprint(os.Stdout, "\n")
    }
}
