            var emoji string
            switch status {
            case "PASS":
                emoji = "🟢"
            case "FAIL":
                emoji = "🔴"
            case "PANIC":
                emoji = "🔴"
            case "SKIP":
                emoji = "🟡"
            case "NOTEST":
                emoji = "🟡"
            default:
                emoji = ""
            }
            if emoji != "" {
                rows[idx][0] = emoji + " " + status
            }
        }
        // recompute widths after emoji
        for i := range widths {
            widths[i] = utf8.RuneCountInString(headers[i]) + 2
        }
        for _, r := range rows {
            for i, c := range r {
                l := utf8.RuneCountInString(c) + 2
                if l > widths[i] {
                    widths[i] = l
                }
            }
        }
    }

    // Output markdown table
    fmt.Fprint(os.Stdout, "|")
    for i, h := range headers {
        w := widths[i]
        visLen := utf8.RuneCountInString(h)
        pad := w - visLen
        left := pad / 2
        right := pad - left
        cell := strings.Repeat(" ", left) + h + strings.Repeat(" ", right)
        fmt.Fprintf(os.Stdout, "%s|", cell)
    }
    fmt.Fprint(os.Stdout, "\n|")
    for i, w := range widths {
        // separator: dashes with length w, but markdown separator uses dashes without spaces: "--------" ?
        // Earlier markdown separator for package table was "|--------|---------|---------|-------|------|------|------|"
        // That's dashes equal to width? For Status column width 8, separator "--------" length 8
        // For Elapsed width 9, separator "---------" length 9
        // So separator cell is strings.Repeat("-", w)
        fmt.Fprintf(os.Stdout, "%s|", strings.Repeat("-", w))
        _ = i
    }
    fmt.Fprint(os.Stdout, "\n")
    for _, r := range rows {
        fmt.Fprint(os.Stdout, "|")
        for i, c := range r {
            w := widths[i]
            visLen := utf8.RuneCountInString(c)
            pad := w - visLen
            // Determine align: Package left, others center
            var cell string
            if i == 2 { // Package left
                if c == "" {
                    cell = strings.Repeat(" ", w)
                } else {
                    cell = " " + c + strings.Repeat(" ", pad-1)
                }
            } else {
                left := pad / 2
                right := pad - left
                cell = strings.Repeat(" ", left) + c + strings.Repeat(" ", right)
            }
            fmt.Fprintf(os.Stdout, "%s|", cell)
        }
        fmt.Fprint(os.Stdout, "\n")
    }
}
